#!/bin/bash\n\n# 🚀 TERMUX PRO - Complete Setup\n# Copilot + GitHub + Chat AI + Beautiful Interface\n\nset -e\n\necho \"\"\necho \"╔════════════════════════════════════════════════════════════╗\"\necho \"║  🚀 TERMUX PRO - Ultimate Developer Environment           ║\"\necho \"║  Copilot + GitHub + Chat IA + Beautiful UI                ║\"\necho \"╚════════════════════════════════════════════════════════════╝\"\necho \"\"\n\nif [ ! -d \"$PREFIX\" ]; then\n    echo \"❌ ERROR: Run this in Termux!\"\n    exit 1\nfi\n\necho \"📦 Step 1/6: Updating packages...\"\npkg update && pkg upgrade -y > /dev/null 2>&1\n\necho \"🐍 Step 2/6: Installing Python & tools...\"\npkg install -y python python-dev clang build-essential git nano curl wget openssh > /dev/null 2>&1\n\necho \"📥 Step 3/6: Installing Python packages...\"\npip install --upgrade pip openai==0.27.8 anthropic requests python-dotenv rich click > /dev/null 2>&1\n\necho \"📁 Step 4/6: Creating workspace structure...\"\nmkdir -p ~/ai-workspace/{chats,generated_code,scripts,config,github}\n\necho \"⬇️  Step 5/6: Downloading scripts...\"\nGITHUB_RAW=\"https://raw.githubusercontent.com/nistordaniel06-cpu/termux-ai-setup/main/scripts\"\n\necho \"  → Downloading chat.py...\"\ncurl -fsSL \"${GITHUB_RAW}/chat.py\" -o ~/ai-workspace/scripts/chat.py 2>/dev/null || true\n\necho \"  → Downloading copilot.py...\"\ncurl -fsSL \"${GITHUB_RAW}/copilot.py\" -o ~/ai-workspace/scripts/copilot.py 2>/dev/null || true\n\necho \"  → Downloading codex_helper.py...\"\ncurl -fsSL \"${GITHUB_RAW}/codex_helper.py\" -o ~/ai-workspace/scripts/codex_helper.py 2>/dev/null || true\n\necho \"  → Downloading termux_pro_hub.py...\"\ncurl -fsSL \"${GITHUB_RAW}/termux_pro_hub.py\" -o ~/ai-workspace/scripts/termux_pro_hub.py 2>/dev/null || true\n\necho \"  → Downloading ai_menu.py...\"\ncurl -fsSL \"${GITHUB_RAW}/ai_menu.py\" -o ~/ai-workspace/scripts/ai_menu.py 2>/dev/null || true\n\nchmod +x ~/ai-workspace/scripts/*.py 2>/dev/null || true\n\necho \"⚙️  Step 6/6: Configuring environment...\"\n\n# Create config\ncat > ~/ai-workspace/config/ai.conf << 'CONF'\n# 🚀 TERMUX PRO Configuration\n# Edit this file and add your API keys\n\nexport OPENAI_API_KEY=\"sk-your-api-key-here\"\nexport GITHUB_TOKEN=\"ghp_your-token-here\"\nexport GITHUB_USER=\"your-username\"\nexport AI_MODEL=\"gpt-3.5-turbo\"\nexport AI_TEMPERATURE=\"0.7\"\nexport AI_MAX_TOKENS=\"1000\"\nCONF\n\n# Create git config helper\ncat > ~/ai-workspace/scripts/git_helper.sh << 'GITHELP'\n#!/bin/bash\n# Git Helper for Termux Pro\n\necho \"🐙 GitHub Setup Helper\"\necho \"\"\n\nread -p \"GitHub username: \" github_user\nread -p \"GitHub email: \" github_email\nread -sp \"GitHub token (paste from https://github.com/settings/tokens): \" github_token\n\ngit config --global user.name \"$github_user\"\ngit config --global user.email \"$github_email\"\n\necho \"\"\necho \"✅ GitHub configured!\"\necho \"Token saved locally (secure).\"\necho \"\"\necho \"Next: Clone a repo with:\"\necho \"  git clone https://$github_token@github.com/username/repo.git\"\nGITHELP\n\nchmod +x ~/ai-workspace/scripts/git_helper.sh\n\n# Update bashrc with new aliases\nif ! grep -q \"TERMUX PRO\" ~/.bashrc 2>/dev/null; then\n    cat >> ~/.bashrc << 'ALIAS'\n\n# ╔════════════════════════════════════════════════════════════╗\n# ║  🚀 TERMUX PRO - Main Hub                                  ║\n# ╚════════════════════════════════════════════════════════════╝\n\nexport AI_WORKSPACE=\"$HOME/ai-workspace\"\n\n# Load configuration\nif [ -f \"$AI_WORKSPACE/config/ai.conf\" ]; then\n    source \"$AI_WORKSPACE/config/ai.conf\"\nfi\n\n# ===== MAIN COMMANDS =====\nalias tp='python $AI_WORKSPACE/scripts/termux_pro_hub.py'  # Main Hub\nalias ai='python $AI_WORKSPACE/scripts/termux_pro_hub.py'  # Same as tp\nalias chat='python $AI_WORKSPACE/scripts/chat.py'\nalias copilot='python $AI_WORKSPACE/scripts/copilot.py'\nalias cop='python $AI_WORKSPACE/scripts/copilot.py'\nalias codex='python $AI_WORKSPACE/scripts/codex_helper.py'\nalias goto_ai='cd $AI_WORKSPACE && ls -la'\nalias ai_config='nano $AI_WORKSPACE/config/ai.conf'\nalias git_setup='bash $AI_WORKSPACE/scripts/git_helper.sh'\n\n# ===== GIT SHORTCUTS =====\nalias gs='git status'\nalias ga='git add .'\nalias gc='git commit -m'\nalias gp='git push'\nalias gl='git log --oneline -n 10'\nalias gb='git branch'\nalias gco='git checkout'\n\n# ===== UTILITY =====\nalias cls='clear'\nalias ll='ls -lah'\nalias py='python'\nalias pip3='pip'\n\nALIAS\nfi\n\nsource ~/.bashrc 2>/dev/null || true\n\necho \"\"\necho \"╔════════════════════════════════════════════════════════════╗\"\necho \"║  ✅ INSTALLATION COMPLETE!                                ║\"\necho \"╚════════════════════════════════════════════════════════════╝\"\necho \"\"\necho \"🎯 NEXT STEPS:\"\necho \"\"\necho \"1️⃣  Setup OpenAI API Key:\"\necho \"   nano ~/ai-workspace/config/ai.conf\"\necho \"   Set: OPENAI_API_KEY='sk-your-actual-key'\"\necho \"\"\necho \"2️⃣  Setup GitHub (Optional):\"\necho \"   git_setup\"\necho \"\"\necho \"3️⃣  Reload shell:\"\necho \"   source ~/.bashrc\"\necho \"\"\necho \"4️⃣  START USING:\"\necho \"\"\necho \"   [🚀 MAIN HUB - Type this first!]\"\necho \"   tp\"\necho \"   ai\"\necho \"\"\necho \"   [💬 Individual Commands]\"\necho \"   chat         → AI Chat\"\necho \"   copilot      → Code Generator\"\necho \"   cop          → Short for copilot\"\necho \"   codex        → Code generation\"\necho \"   gs, ga, gp   → Git shortcuts\"\necho \"\"\necho \"═══════════════════════════════════════════════════════════\"\necho \"\"\necho \"💡 Pro Tip: Start with 'tp' or 'ai' for the full hub!\"\necho \"\"\n"